import{n as e,t}from"./jsx-runtime-lw2jiZar.js";import{t as n}from"./archive-9a0QBsx1.js";import{A as r,C as i,E as a,M as o,N as s,O as c,P as l,b as u,k as d,l as f,n as p,o as m,p as h,t as g,v as _}from"./shared-C5BCElVa.js";import{A as v}from"./index-D5bsO7MS.js";import{t as y}from"./CodeEditor-BZlrvoTL.js";var b=e(`ArrowRightLeft`,[[`path`,{d:`m16 3 4 4-4 4`,key:`1x1c3m`}],[`path`,{d:`M20 7H4`,key:`zbl0bi`}],[`path`,{d:`m8 21-4-4 4-4`,key:`h9nckh`}],[`path`,{d:`M4 17h16`,key:`g4d7ey`}]]),x=t(),S=`Этап 4 · Блок 15 · Полный SQL-путь и единое переключение Planner`;function C({module:e}){return(0,x.jsxs)(s,{children:[(0,x.jsx)(o,{variant:`project`,chip:e??S,title:`Переход на SQLite`,intro:`Перенесём актуальные задачи и направим обычные API и CLI в одну базу, сохранив прежнее поведение Planner.`,tags:[{icon:(0,x.jsx)(n,{size:14}),label:`актуальный снимок`},{icon:(0,x.jsx)(b,{size:14}),label:`одна точка переключения`},{icon:(0,x.jsx)(v,{size:14}),label:`сверка данных`}]}),(0,x.jsxs)(l,{number:`00`,title:`От репетиции переноса к общей базе`,children:[(0,x.jsx)(c,{children:`В предыдущих шагах мы подготовили SQL-путь для задач и проверили импорт на копии JSON. Такая копия помогла испытать инструмент, но не обновлялась вместе с рабочим Planner. Теперь нас интересует не только перенос строк, но и момент, когда API и CLI начинают читать и изменять один источник.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Точка старта`,description:`Рабочие API и CLI пока используют JSON; SQL CRUD, короткие ресурсы и импортёр должны быть приняты на шаге готовности.`},{title:`Новый вопрос`,description:`Как перенести именно последнее состояние и не оставить один интерфейс на JSON, а второй на SQLite?`},{title:`Результат`,description:`Мы переносим проверенный снимок и переключаем две обычные сборки на один DATABASE_URL.`}]}),(0,x.jsx)(`p`,{children:`Сначала подтвердим входные условия. План перехода предполагает, что SQL-операции, API-подмена, CLI с Session на команду и репетиция импорта уже прошли общую приёмку. Номер занятия сам по себе этого не доказывает. Если такой результат не подтверждён журналом и кодом, мы останавливаем переключение и возвращаем конкретный пробел на предыдущий шаг.`}),(0,x.jsx)(`p`,{children:`Если допуск пройден, порядок будет таким: остановить записи, сохранить окончательный JSON, импортировать его в ожидаемую пустую базу, сравнить данные, затем сменить настройки двух интерфейсов и проверить их на новых ресурсах. Удаление старых классов хранения не входит в эту работу.`})]}),(0,x.jsxs)(l,{number:`01`,title:`Репетиция и окончательный снимок отвечают на разные вопросы`,children:[(0,x.jsx)(`p`,{children:`Импорт в предыдущем шаге подтверждал, что команда умеет прочитать допустимый JSON, проверить записи и атомарно записать их в пустую таблицу. Он не подтверждал, что тестовая база содержит самые свежие задачи. Пока обычный API или CLI меняет рабочий файл, любая копия, снятая раньше, постепенно расходится с ним.`}),(0,x.jsx)(`p`,{children:`Представим закрытие кассы. Копия отчёта, сделанная вчера, показывает, что бухгалтерская форма правильно переносит суммы. Она не заменяет итоговый отчёт после сегодняшней смены. Для нашего Planner окончательный снимок берётся из фактического JSON_PATH непосредственно перед импортом, когда все записи уже остановлены. Аналогия ограничена: приложение может иметь несколько запущенных процессов, поэтому мы проверяем не только время копирования, но и отсутствие работающих писателей.`}),(0,x.jsx)(`p`,{children:`Слово «источник» здесь означает место, которому мы доверяем как последнему состоянию задач. До переключения это рабочий JSON. После подтверждённого импорта и первой новой SQL-записи таким источником становится SQLite. Архивный JSON остаётся полезен для сравнения и восстановления по отдельной процедуре, но сам не получает изменения из базы.`}),(0,x.jsx)(u,{question:`Какой файл является источником для окончательного переноса?`,options:[`Копия, которую импортировали в ходе репетиции`,`Рабочий JSON, скопированный после остановки всех записей`,`Любой JSON с тем же числом строк, что и SQLite`],correctIndex:1,explanation:`Репетиция проверяла инструмент. Источником последнего состояния остаётся рабочий JSON до момента остановки писателей; одинаковое число строк не подтверждает одинаковое содержимое.`})]}),(0,x.jsxs)(l,{number:`02`,title:`Сначала замораживаем записи и проверяем адреса`,children:[(0,x.jsx)(`p`,{children:`Снимок надёжен только в том случае, если исходный список не меняется во время его чтения и переноса. Поэтому мы останавливаем обе обычные точки записи, API и CLI, и дожидаемся завершения уже начатых действий. Если процесс остаётся активен или непонятно, какой JSON читает конфигурация, нельзя продолжать по догадке.`}),(0,x.jsx)(`p`,{children:`Путь берём из разрешённого значения Settings.json_path, а не из текущей папки терминала. Для резервной копии фиксируем исходный путь и момент снимка. Копия не заменяет JSON_PATH и не становится новым рабочим хранилищем. Она сохраняет возможность сверить исходное состояние после завершения перехода.`}),(0,x.jsx)(`p`,{children:`Цель также проверяем явно: DATABASE_URL должен указывать на ожидаемый файл SQLite, таблица должна иметь исходную схему, созданную раньше, а таблица задач должна быть пустой. Пустой файл по знакомому имени ещё не доказывает, что адрес выбран верно. Если база непустая, схема неизвестна или путь ведёт в другое место, мы останавливаемся и выясняем назначение файла. Команда импорта не должна автоматически очищать цель или создавать схему вместо отдельной команды инициализации.`}),(0,x.jsx)(`p`,{children:`В Windows сначала смотрим, какие Python-процессы запущены. Get-CimInstance получает сведения процесса из Windows: ProcessId означает PID, ExecutablePath показывает путь к Python, а CommandLine содержит команду запуска и её аргументы. По командной строке сверяем путь проекта или точку входа API/CLI. Если один и тот же Python используется разными проектами и принадлежность не ясна, процесс не останавливаем и не считаем писателя остановленным.`}),(0,x.jsx)(y,{caption:`PowerShell: список Python-процессов без остановки`,code:`Get-CimInstance Win32_Process -Filter "Name='python.exe' OR Name='pythonw.exe'" |
  Select-Object ProcessId, ExecutablePath, CommandLine`}),(0,x.jsx)(`p`,{children:`Для API отдельно проверяем настроенный порт. Команда ниже показывает OwningProcess, то есть PID процесса, который слушает 8001. Если в конфигурации задан другой порт, подставляем его вместо 8001. Сопоставляем OwningProcess с ProcessId и только затем проверяем путь и командную строку найденного процесса.`}),(0,x.jsx)(y,{caption:`PowerShell: PID владельца порта API, пример для 8001`,code:`Get-NetTCPConnection -State Listen -LocalPort 8001 |
  Select-Object LocalAddress, LocalPort, OwningProcess`}),(0,x.jsx)(`p`,{children:`Если процесс на порту принадлежит другому проекту, оставляем его работать и продолжаем искать API StudyHub. CLI может не слушать порт, поэтому его отдельно сверяем по командной строке и останавливаем через Ctrl+C в его терминале. Если API запускает другой человек или его терминал недоступен, Stop-Process -Id <PID> применяем только к PID, который уже подтверждён по пути, командной строке и порту; вместо <PID> подставляем число ProcessId. Неясная принадлежность означает, что переход пока не готов.`}),(0,x.jsx)(_,{code:`def choose_next_step(sql_ready, writers_stopped, target_empty):
    if not sql_ready:
        return "stop: complete the readiness check"
    if not writers_stopped:
        return "stop: freeze JSON writes"
    if not target_empty:
        return "stop: inspect the database"
    return "import the final snapshot"`,steps:[{line:1,note:`Функция получает три подтверждения. Это учебная модель допуска, а не автоматический переключатель.`},{line:2,note:`Если SQL-сценарий не принят, мы возвращаемся к проверке готовности и не трогаем обычную сборку.`},{line:4,note:`Даже готовый SQL-код недостаточен, пока JSON может получить новую запись.`},{line:6,note:`Неизвестную или непустую базу сначала исследуем. Мы не удаляем существующие данные.`},{line:7,note:`Импорт допустим только после всех трёх проверок: SQL готов, писатели остановлены, цель ожидаемая и пустая.`}]}),(0,x.jsx)(i,{code:`# Условный вывод, не команда запуска
# PID: 4120
# ExecutablePath: C:/apps/archive/.venv/Scripts/python.exe
# CommandLine: python -m uvicorn archive.api:app --port 8001

# Неверный вывод: это точно API StudyHub`,question:`Как поступим с этим слушателем перед снимком?`,options:[`Сверим PID, ExecutablePath и CommandLine; если это другой проект, оставим его работать`,`Остановим PID 4120, потому что он слушает порт 8001`,`Остановим все Python-процессы, чтобы закрыть API и CLI`],correctIndex:0,explanation:`Путь и командная строка указывают на archive, а порт связывает PID с API этого проекта. Мы не останавливаем его и не считаем писателей StudyHub остановленными, пока отдельно не подтвердили процессы StudyHub.`,fix:`# Сопоставляем OwningProcess с ProcessId
# подтверждаем проект по ExecutablePath и CommandLine
# чужой процесс оставляем работать`}),(0,x.jsx)(`p`,{children:`Этот порядок похож на остановку конвейера перед заменой ленты: мы сперва прекращаем новые поступления, затем фиксируем содержимое, после чего меняем получателя. Сравнение не означает, что две базы синхронизируются автоматически. Оно только помогает увидеть, почему переключение нельзя начинать между двумя ещё работающими интерфейсами.`})]}),(0,x.jsxs)(l,{number:`03`,title:`Импортируем один снимок и доказываем равенство`,children:[(0,x.jsx)(`p`,{children:`В готовом импортёре уже есть проверка входа и одна транзакция для записи снимка. Мы используем этот инструмент с явными source и database URL, не добавляя импорт в запуск FastAPI, открытие Session или каждую команду CLI. Повторный запуск на непустой цели должен завершиться отказом, а не объединением двух списков.`}),(0,x.jsx)(`p`,{children:`После записи мы читаем таблицу новой Session и сравниваем не только количество строк. Для каждой задачи проверяем id, title, priority, is_done и tags. Теги являются внутренней частью Task и остаются важны, хотя публичная HTTP-схема показывает только четыре поля. Отдельно проверяем title_normalized: это служебная колонка, которая поддерживает прежний поиск и не добавляется в HTTP-ответ.`}),(0,x.jsx)(`p`,{children:`В независимом примере складской перенос проверял бы для каждой позиции код, название, количество и категорию. Две ведомости с одинаковым числом строк могли бы различаться на одной позиции, поэтому сравнивается отображение «код → все значимые поля». Для Task работает тот же принцип: равенство полного набора id и значений подтверждает точность лучше, чем счётчик импорта.`}),(0,x.jsx)(`p`,{children:`Старый допустимый формат без tags остаётся допустимым по правилам импортёра и получает пустой список. Мы не вводим задним числом HTTP-ограничение длины заголовка для исторической CLI-записи. Если любая строка не проходит проверку, результат не считаем перенесённым и не направляем интерфейсы на эту базу.`}),(0,x.jsx)(h,{prompt:`Сопоставим наблюдение с тем, что оно подтверждает.`,leftTitle:`Наблюдение`,rightTitle:`Вывод`,pairs:[{left:`Импортёр обработал 24 строки`,right:`Известно количество, но не все значения`},{left:`Новая Session прочитала совпадающие поля каждой задачи`,right:`Содержимое базы сверено с копией`},{left:`После отказа исходный JSON сохранил прежний hash`,right:`Файл не был изменён импортом`},{left:`Непустая цель отклонила повторный импорт`,right:`Данные не объединялись молча`}],explanation:`Каждое наблюдение отвечает на отдельный вопрос: объём, содержимое, сохранность источника или безопасный отказ. Для допуска нам нужны все эти доказательства.`})]}),(0,x.jsxs)(l,{number:`04`,title:`Переключаем API и CLI на один адрес, сохраняя короткие ресурсы`,children:[(0,x.jsx)(`p`,{children:`После точной сверки меняется обычная сборка приложения. API получает SQL-сервис с Session текущего запроса через уже подготовленную get_db. CLI получает SQL-сервис с отдельной Session на распознанную команду через ресурсный путь, подготовленный раньше. Каждый процесс переиспользует собственные Engine и SessionFactory. API и CLI используют один DATABASE_URL, но не разделяют живую Session или объекты подключения.`}),(0,x.jsx)(`p`,{children:`Представим две стойки обслуживания, которые работают с одним каталогом. Каждая открывает собственную рабочую карточку, читает или меняет запись и закрывает её после действия. Общий каталог соответствует адресу базы и фабрике, а отдельная карточка помогает увидеть короткую Session. Граница аналогии в том, что Session не просто бумажный талон: она отслеживает ORM-объекты и транзакционную работу, поэтому её жизненный цикл важен для корректного состояния.`}),(0,x.jsx)(`p`,{children:`Провайдер API собирает сервис вокруг Session запроса. В приложении можно хранить Settings и фабрику, но не SQL-сервис, навсегда связанный с одной уже открытой Session. FastAPI выполняет очистку yield-зависимости по правилам выбранной версии и scope; мы не связываем подтверждение SQL-записи с поздним cleanup. Сценарий сервиса завершает транзакцию до сообщения об успехе.`}),(0,x.jsx)(y,{caption:`Фрагмент API-provider после допуска SQL-пути`,code:`def get_planner(db: Session = Depends(get_db)) -> PlannerService:
    return PlannerService(
        repository=SqlTaskRepository(db),
        write_scope=db.begin,
    )`}),(0,x.jsx)(`p`,{children:`В CLI сохраняются существующие run, диспетчер и обработчики команд. Меняется источник сервиса: настройки дают тот же DATABASE_URL, а распознанная команда входит в уже подготовленный SQL-контекст и закрывает свою Session при выходе. exit и неизвестная команда не требуют открытия базы. Мы не пересобираем меню, тексты сообщений, поиск, selection или HTTP-маршруты.`}),(0,x.jsx)(`p`,{children:`После переключения ни одна обычная точка входа не должна выбирать JSON как default или незаметный fallback. Классы JsonStorage и адаптер могут пока оставаться в коде без активных потребителей. Их удаление относится к следующему занятию, когда сначала будет найден каждый импорт и вызов.`}),(0,x.jsx)(i,{code:`def configure_app(app, settings):
    db = app.state.session_factory()
    app.state.planner = build_service(
        repository=SqlTaskRepository(db)
    )
    app.state.db = db`,question:`Что здесь нарушает границу ресурса API?`,options:[`Одна Session создаётся при сборке приложения и сохраняется для всех будущих запросов`,`Настройки передаются в функцию сборки`,`SQL-репозиторий получает Session через аргумент`],correctIndex:0,explanation:`app.state может хранить повторно используемую фабрику, но Session и собранный поверх неё сервис принадлежат одному действию. Разделим создание Session и получение сервиса на уровне запроса.`,fix:`def get_planner(db: Session = Depends(get_db)) -> PlannerService:
    return build_service(repository=SqlTaskRepository(db))`}),(0,x.jsx)(`p`,{children:`На схеме показан только успешный маршрут переключения. Слева направо мы останавливаем записи, фиксируем последний JSON, импортируем его, сверяем каждое поле и только затем отправляем оба интерфейса к общей базе. Если импорт или сравнение не проходит, поток останавливается до смены сборок.`}),(0,x.jsx)(g,{caption:`Порядок перехода от рабочего JSON к общей SQLite`,children:(0,x.jsxs)(m,{label:`Остановка писателей, снимок, импорт, сверка и включение двух интерфейсов`,children:[(0,x.jsx)(f,{title:`API и CLI остановлены`,shape:`terminator`,children:(0,x.jsx)(`p`,{children:`Новых записей в JSON нет`})}),(0,x.jsx)(p,{label:`копия JSON_PATH`}),(0,x.jsx)(f,{title:`Окончательный снимок`,shape:`process`,children:(0,x.jsx)(`p`,{children:`Источник и время зафиксированы`})}),(0,x.jsx)(p,{label:`одна транзакция`}),(0,x.jsx)(f,{title:`SQLite импортирована`,shape:`database`,children:(0,x.jsx)(`p`,{children:`Схема ожидаемая, таблица была пустой`})}),(0,x.jsx)(p,{label:`новая Session`}),(0,x.jsx)(f,{title:`Поля совпали`,children:(0,x.jsx)(`p`,{children:`id, данные, tags и title_normalized`})}),(0,x.jsx)(p,{label:`тот же DATABASE_URL`}),(0,x.jsx)(f,{title:`API и CLI используют SQLite`,shape:`terminator`,children:(0,x.jsx)(`p`,{children:`Каждое действие открывает свой ресурс`})})]})}),(0,x.jsx)(a,{tone:`warn`,children:`Непустая цель, неуспешный импорт, несовпадение полей или продолжающийся JSON-писатель означают остановку. Нельзя переключать только один интерфейс или продолжать после частичного допуска.`})]}),(0,x.jsxs)(l,{number:`05`,title:`Проверяем обмен состоянием на новых запросах и командах`,children:[(0,x.jsx)(`p`,{children:`Проверка в той же Session может вернуть уже известный ORM-объект и не показывает, что другая точка входа видит commit. Поэтому после запуска обеих сборок используем отдельные действия: API создаёт контрольную задачу, CLI находит и завершает её, новый API-запрос читает статус и статистику. Затем CLI выполняет поиск по существующему пути. HTTP search-route для этого не добавляем.`}),(0,x.jsx)(`p`,{children:`Отдельно проходим прежние PUT, PATCH и DELETE на безопасной приёмочной задаче. Сверяем публичные коды и ответы, прежнюю семантику пустого PATCH и false, внутренние tags, сохранность соседней задачи и появление результата через новый ресурс. Контракт не меняется только потому, что изменилось хранение.`}),(0,x.jsx)(`p`,{children:`Новая сборка API и новый CLI-процесс используют тот же адрес и снова читают изменённое состояние. Это проверяет постоянство SQLite после закрытия Session и перезапуска, а не объект в памяти. До первых новых SQL-изменений также проверяем, что импорт и запуск не меняли исходный архив JSON.`}),(0,x.jsx)(r,{rows:[[`Проверка`,`Что подтверждаем`],[`API create → CLI find/done`,`CLI видит задачу, созданную API, и сохраняет изменение`],[`Новый API get/stats`,`Следующий запрос видит SQL-состояние после CLI`],[`Новый запуск`,`Сохранённые изменения доступны после закрытия прежних ресурсов`],[`Hash JSON`,`Обычные действия после переключения не записывают в архив`]]})]}),(0,x.jsxs)(l,{number:`06`,title:`После первой SQL-записи меняется граница восстановления`,children:[(0,x.jsx)(`p`,{children:`Сразу после переноса архив JSON ещё совпадает с SQLite. Когда API или CLI успешно сохраняет новое состояние в SQLite, архив отстаёт. Если просто вернуть старый JSON_PATH, Planner покажет прежние данные и потеряет видимость новых задач. Это не ошибка транзакции: это следствие того, что два хранилища больше не синхронизируются.`}),(0,x.jsx)(`p`,{children:`До первой новой SQL-записи незавершённый переход можно остановить, сохранив снимок и выяснив причину отказа. После записи мы не делаем автоматический возврат на архив. Если нужен обратный перенос, потребуется отдельная процедура, которая сохранит новые SQL-изменения и проверит их перед сменой источника. Такой сценарий здесь не проектируем.`}),(0,x.jsx)(`p`,{children:`Старый backend также не удаляем в этом шаге. Сначала подтверждаем, что API и CLI работают только через SQL. В следующем занятии отдельно ищем runtime-потребителей JsonStorage, JSON_PATH и переходного адаптера, затем удаляем код и проверяем независимость от старого файла.`}),(0,x.jsx)(h,{prompt:`Выберем безопасное действие для каждого момента.`,leftTitle:`Момент`,rightTitle:`Действие`,pairs:[{left:`До первой записи в SQLite`,right:`Остановить незавершённый переход и выяснить причину`},{left:`После новой SQL-записи`,right:`Не возвращать старый JSON как будто он актуален`},{left:`Переход подтверждён, legacy-код ещё есть`,right:`Удалять его отдельным шагом после поиска потребителей`}],explanation:`Решение зависит от того, появились ли изменения, которых нет в архиве. Простая смена настройки после commit не переносит эти данные назад.`})]}),(0,x.jsxs)(l,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,x.jsx)(c,{children:`Завершим управляемое переключение уже готового Planner. Мы не пишем повторно SQL CRUD, ресурсные зависимости или импортёр, а соединяем их проверенные результаты.`}),(0,x.jsx)(d,{variant:`connected`,items:[{title:`Подтвердим допуск и остановим записи`,description:`Сверим результат 74.1, установим принадлежность API и CLI по PID, пути и командной строке, остановим только процессы StudyHub и определим JSON_PATH.`},{title:`Сохраним и перенесём снимок`,description:`Скопируем последний JSON, проверим пустую целевую таблицу и запустим готовый импортёр с явным DATABASE_URL.`},{title:`Сверим и переключим сборки`,description:`Сравним id и все поля новой Session, затем направим API и CLI на один SQL-путь без изменения их договора.`},{title:`Докажем общий результат`,description:`Проверим API create, CLI find/done, новый API get/stats, поиск, CRUD и повторный запуск; зафиксируем границу архива.`}]}),(0,x.jsx)(`p`,{children:`Первая карточка практики является настоящим допуском, а не формальностью. Если журнал или код не подтверждает все необходимые результаты 97, мы не выполняем зависимые шаги и называем конкретную недостающую проверку. Если импорт не совпал, база оказалась непустой или один из интерфейсов продолжает писать в JSON, переключение также останавливается. Успехом считается только общий SQL-путь с точными данными и сохранённым поведением API и CLI.`})]})]})}export{C as Lesson75};